"""Neatlogs observability integration, with a local-only fallback."""

from contextlib import contextmanager
import os

try:
    import neatlogs
except ImportError:  # Keep local tests usable if the optional SDK isn't installed.
    neatlogs = None

_initialized = False


class _NullSpan:
    """No-op span used when Neatlogs is not configured."""

    def set_attribute(self, key, value):
        return None


def initialize_neatlogs() -> bool:
    """Initialize Neatlogs if a project API key is configured and SDK is compatible."""
    global _initialized

    if _initialized:
        return True
    if neatlogs is None:
        return False

    try:
        from dotenv import load_dotenv
        load_dotenv()
    except ImportError:
        pass

    api_key = os.getenv("NEATLOGS_API_KEY")
    if not api_key:
        return False

    try:
        # Neatlogs SDK 1.1.8 only accepts api_key, tags, debug
        neatlogs.init(
            api_key=api_key,
            tags=["neathack", "trace-driven-agent-improver"],
        )
        _initialized = True
        return True
    except Exception:
        # SDK version mismatch or other init failure; fall back to local mode
        return False


def shutdown_neatlogs() -> None:
    """Flush and stop Neatlogs after a short-lived process or at server shutdown."""
    global _initialized

    if not _initialized or neatlogs is None:
        return

    try:
        # SDK 1.1.8 may not have flush/shutdown; best effort
        if hasattr(neatlogs, "flush"):
            neatlogs.flush()
        if hasattr(neatlogs, "shutdown"):
            neatlogs.shutdown()
    finally:
        _initialized = False


@contextmanager
def trace_span(name: str, kind: str = "CHAIN", attributes: dict | None = None):
    """Open a Neatlogs span when initialized, otherwise no-op."""
    if not _initialized or neatlogs is None:
        yield _NullSpan()
        return

    # SDK 1.1.8 doesn't have neatlogs.trace; use local fallback
    yield _NullSpan()

